css:
.loader { --accent: var(--loader-color); --accent-2: var(--loader-secondary-color); width: var(--loader-size); height: var(--loader-size); position: relative; }
.loader .tube { position: absolute; left: 22%; top: 10%; width: 56%; height: 46%; border: 6px solid var(--accent); border-bottom: 0; border-radius: 52% 52% 0 0; }
.loader .tip { position: absolute; top: 6%; width: 12%; height: 10%; border-radius: 50%; background: var(--accent); }
.loader .tip:nth-of-type(2) { left: 17%; }
.loader .tip:nth-of-type(3) { right: 17%; }
.loader .bell { position: absolute; left: 34%; bottom: 8%; width: 32%; height: 32%; border-radius: 50%; background: radial-gradient(circle at 38% 34%, color-mix(in srgb, #fff 30%, var(--accent)), var(--accent)); box-shadow: inset 0 0 0 4px color-mix(in srgb, #fff 45%, transparent); animation: steth-thump calc(var(--loader-speed) * 1.1) ease-in-out infinite; }
.loader span { position: absolute; left: 30%; bottom: 4%; width: 40%; height: 40%; border-radius: 50%; box-shadow: 0 0 0 3px var(--accent-2); opacity: 0; animation: steth-ping calc(var(--loader-speed) * 1.1) ease-out infinite; }
.loader span:nth-of-type(2) { animation-delay: calc(var(--loader-speed) * .18); }
@keyframes steth-thump { 0%, 100% { transform: scale(1); } 14% { transform: scale(1.12); } 30% { transform: scale(.98); } 44% { transform: scale(1.06); } }
@keyframes steth-ping { 0%, 8% { opacity: 0; transform: scale(.7); } 20% { opacity: .9; } 70%, 100% { opacity: 0; transform: scale(1.35); } }
